.itinerary-map-panel.full-page .journey-map-shell.full-page-map .world-grid{
  transform-origin:center center!important;
  transform:translate(calc(var(--map-pan-x,0) * 1%),calc(var(--map-pan-y,0) * 1%)) scale(var(--map-zoom,1))!important;
}
.journey-map-shell.full-page-map .geo-pin,
.itinerary-map-shell.full-page-map .geo-pin{transform:translate(-50%,-50%) scale(var(--pin-scale,1))!important;transform-origin:center center!important}
.itinerary-map-shell:not(.full-page-map) .route-group:nth-of-type(n/**/+7),
.itinerary-map-shell:not(.full-page-map) .geo-pin:nth-of-type(n/**/+7){display:none!important}
.itinerary-map-shell:not(.full-page-map) .route-segment{stroke-width:1.45!important;opacity:.86!important}
