/* Itinerary — the compact-landscape lock forced an 82px action rail while
   retaining two certified 44px controls. On the physical iPad this pushed the
   delete action through the right edge. Give both controls a mathematically
   valid rail at 1180/1194-class widths, and stack them only at 1024-class. */
@media (min-width:1051px) and (max-width:1250px) and (orientation:landscape){
  body[data-screen="itinerary"] .itinerary-card{
    grid-template-columns:142px minmax(0,1fr) 112px!important;
  }
  body[data-screen="itinerary"] .itinerary-card-actions{
    justify-content:center!important;gap:6px!important;padding:7px!important;font-size:0!important;
  }
  body[data-screen="itinerary"] .itinerary-card-actions button{
    flex:0 0 44px!important;width:44px!important;min-width:44px!important;max-width:44px!important;
    height:44px!important;min-height:44px!important;padding:0!important;
    display:inline-grid!important;place-items:center!important;
  }
}
@media (max-width:1050px) and (orientation:landscape){
  body[data-screen="itinerary"] .itinerary-card{
    grid-template-columns:132px minmax(0,1fr) 60px!important;
  }
  body[data-screen="itinerary"] .itinerary-card-actions{
    flex-direction:column!important;justify-content:center!important;gap:5px!important;padding:6px 7px!important;font-size:0!important;
