/* Calendar — the locked 1180/1194 one-screen month uses 82px day cells. A
   transition label plus the 36px event card exceeded that cell height, so the
   following event was visibly cropped on transition days. Compact only those
   transition stacks; normal event cards keep the approved two-line treatment. */
@media (min-width:1051px) and (max-width:1400px) and (orientation:landscape){
  body[data-screen="calendar"] .calendar-large .day.transition-day{
    padding-top:4px!important;padding-bottom:4px!important;
  }
  body[data-screen="calendar"] .calendar-large .day.transition-day .day-num{
    font-size:12px!important;line-height:1!important;
  }
  body[data-screen="calendar"] .calendar-large .day.transition-day .destination-stay-label.transition-label{
    margin:2px 0!important;padding:2px 4px!important;gap:0!important;min-height:0!important;
  }
  body[data-screen="calendar"] .calendar-large .day.transition-day .destination-stay-label.transition-label>b,
  body[data-screen="calendar"] .calendar-large .day.transition-day .destination-stay-label.transition-label>b span{
    font-size:7.6px!important;line-height:1!important;
  }
  body[data-screen="calendar"] .calendar-large .day.transition-day .destination-stay-label.transition-label>small{
    margin-top:1px!important;font-size:5.5px!important;line-height:1!important;letter-spacing:0!important;
  }
  body[data-screen="calendar"] .calendar-large .day.transition-day .event{
    min-height:27px!important;height:27px!important;margin-top:2px!important;padding:2px 3px!important;
    grid-template-columns:15px minmax(0,1fr)!important;grid-template-rows:9px minmax(0,1fr)!important;
    column-gap:3px!important;row-gap:0!important;
  }
  body[data-screen="calendar"] .calendar-large .day.transition-day .event>i{
    width:15px!important;min-width:15px!important;height:15px!important;
  }
  body[data-screen="calendar"] .calendar-large .day.transition-day .event>small{
    font-size:6.1px!important;line-height:1!important;
  }
  body[data-screen="calendar"] .calendar-large .day.transition-day .event>b{
    font-size:7.2px!important;line-height:1!important;-webkit-line-clamp:2!important;
  }
}

