body[data-screen="calendar"] :is(.calendar-day-view,.calendar-selected-panel,.calendar-filter-panel){
  box-shadow:inset 0 1px rgba(255,255,255,.09),0 10px 24px rgba(0,0,0,.25)!important;
}
body[data-screen="calendar"] .day-agenda-row{
  border-left:4px solid var(--day-accent,#58cfff)!important;
  box-shadow:inset 0 1px rgba(255,255,255,.075),inset 0 -9px 16px rgba(0,0,0,.09),0 5px 13px rgba(0,0,0,.18)!important;
}

/* Vault Streaming, hidden email store, toilet phrase and country quick-look
   are real app screens/panels too; give them the same premium finish. */
body[data-screen="vault"] .vault-streaming-panel{
  border-top-color:#79dcf7!important;
  box-shadow:0 30px 88px rgba(0,0,0,.70),0 0 32px rgba(79,198,239,.15),inset 0 1px rgba(255,255,255,.10)!important;
}
body[data-screen="vault"] :is(.vault-streaming-app-tile,.vault-streaming-credential-readout,.vault-streaming-detail,.vault-streaming-editor){
  box-shadow:inset 0 1px rgba(255,255,255,.085),inset 0 -10px 18px rgba(0,0,0,.08),0 5px 14px rgba(0,0,0,.20)!important;
}
body[data-screen="vault"] .vault-streaming-email-panel{
  border-top-color:#8be5fa!important;
  box-shadow:0 31px 92px rgba(0,0,0,.76),0 0 34px rgba(83,205,240,.17),inset 0 1px rgba(255,255,255,.11)!important;
}
body[data-screen="vault"] .vault-streaming-email-fields label{
  box-shadow:inset 0 1px rgba(255,255,255,.055),0 4px 11px rgba(0,0,0,.15)!important;
}
.toilet-phrase-panel,.country-quick-look-panel{
  border-top-color:#8ae3ff!important;
  box-shadow:0 30px 92px rgba(0,0,0,.68),0 0 34px rgba(72,193,238,.15),inset 0 1px rgba(255,255,255,.10)!important;
}
.country-quick-look-panel :is(.country-quick-look-grid>div,.country-quick-look-plant){
  box-shadow:inset 0 1px rgba(255,255,255,.075),0 5px 14px rgba(0,0,0,.18)!important;
}

/* Settings App Health expanded result rows and details are part of the opened
   health experience, so they receive the same cyan health edge treatment. */
body[data-screen="settings"] #screen :is(.app-health-row[open],.app-health-row-details,.app-health-result){
  border-color:rgba(86,185,217,.48)!important;
  box-shadow:inset 0 1px rgba(255,255,255,.075),inset 0 0 18px rgba(65,182,220,.05),0 5px 14px rgba(0,0,0,.18)!important;
}

/* Checklist focus/quick screens keep the source list identity and never replace
   the large Ready to Move widget's purpose. */
body[data-screen="checklist"] .checklist-ready-panel h2{white-space:nowrap!important}

/* Controls inside any opened surface have consistent tactile depth without
   replacing their authored colour. */
:is(#modal,.readability-focus-panel,.journey-focus-panel,.checklist-focus-panel,.vault-streaming-panel,.vault-streaming-email-panel,.toilet-phrase-panel,.country-quick-look-panel) button{
  box-shadow:inset 0 1px rgba(255,255,255,.10),0 4px 11px rgba(0,0,0,.18);
}
